<?php
namespace App\Console\Commands;
use Illuminate\Console\Command;
use App\Services\Zernio\ZernioClient;
class ConfigureZernioWebhook extends Command {protected $signature='zernio:webhook {--url= : Public webhook URL} {--test= : Webhook id to test}';protected $description='Create a production Zernio webhook subscription';public function handle(ZernioClient $z):int{$secret=config('zernio.webhook_secret');if(!$secret){$this->error('ZERNIO_WEBHOOK_SECRET is required.');return self::FAILURE;}if($id=$this->option('test')){$r=$z->testWebhook($id);$this->line(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));return self::SUCCESS;}$url=$this->option('url')?:rtrim(config('app.url'),'/').'/api/webhooks/zernio';$events=['comment.received','message.received','message.sent','message.delivered','message.read','message.failed','message.deleted','message.edited','reaction.received','conversation.started','conversation.control_changed'];$data=['name'=>'Instagram Automation Production','url'=>$url,'secret'=>$secret,'events'=>$events];if($accountId=env('ZERNIO_ACCOUNT_ID'))$data['accountIds']=[$accountId];$r=$z->configureWebhooks($data);$this->line(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));return self::SUCCESS;}}
